
import type { CreditNoteLine } from './CreditNoteLine.js';
import type { DocumentTaxID } from './DocumentTaxID.js';
import type { MoneyValue } from './MoneyValue.js';

/** A correction against an issued invoice. Credit notes reduce what is owed; refunds return what was already collected. */ export type CreditNote = { /** Identity frozen on the source invoice at issue. Later profile edits do not change this document. */ "buyer_tax_identity"?: (({ /** minLength: 1. maxLength: 255. */ "legal_name"?: string | null; "registered_address"?: (({ "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }) | (null)); /** maxItems: 20. */ "tax_ids": Array<DocumentTaxID>; }) | (null)); /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "credit_note_id": string; "credit_note_lines": Array<CreditNoteLine>; /** Assigned at issue and stable from then on. Absent while the credit note is a draft. */ "credit_note_number"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "invoice_id": string; /** RFC3339 timestamp. Format: date-time. */ "issued_at"?: string; "latest_refund_status"?: "pending" | "in_transit" | "succeeded" | "failed" | "requires_action" | "canceled" | "partially_succeeded" | (string & {}); /** Free text shown on the credit note, up to 4096 characters. */ "memo"?: string; "merchant_id": string; "pending_refund_money": MoneyValue; /** Why the invoice is being corrected. Shown on the credit note document. */ "reason": "returned_goods" | "order_adjustment" | "billing_error" | "goodwill" | "other" | (string & {}); "refunded_money": MoneyValue; /** Identity frozen on the source invoice at issue. Later profile edits do not change this document. */ "seller_tax_identity"?: (({ /** minLength: 1. maxLength: 255. */ "legal_name"?: string | null; "registered_address"?: (({ "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }) | (null)); /** maxItems: 20. */ "tax_ids": Array<DocumentTaxID>; }) | (null)); /** draft while the credit note is editable, issued once it is numbered and frozen, void once retired. */ "status": "draft" | "issued" | "void" | (string & {}); /** The face value of the credit note, the sum of its lines. */ "total_money": MoneyValue; /** Credit still available to allocate. Equals total_money at issue, falls as credit is applied, and rises again when an allocation is reversed. */ "unallocated_money": MoneyValue; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Current credit note version. Send this as expected_version when updating the draft. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "version": string; /** RFC3339 timestamp. Format: date-time. */ "voided_at"?: string; };
